describe('Internal Links - Same Tab Opening', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should open internal links in the same tab', () => {
    // Verify initial page is loaded
    cy.get('[data-testid="dashboard-header"]').should('be.visible');

    // Click on an internal link
    cy.get('[data-testid="dashboard-settings-link"]').click();

    // Verify the same tab is active
    cy.get('[data-testid="dashboard-header"]').should('be.visible');
    cy.get('[data-testid="dashboard-settings-panel"]').should('be.visible');

    // Verify the URL has changed to the internal link
    cy.url().should('include', '/dashboard/settings');

    // Verify the content of the new tab matches the expected content
    cy.get('[data-testid="settings-title"]').should('contain', 'Settings');
    cy.get('[data-testid="settings-description"]').should('contain', 'Manage your account settings');

    // Verify the back button returns to the original tab
    cy.get('[data-testid="dashboard-settings-back-button"]').click();
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="dashboard-header"]').should('be.visible');
  });

  it('should handle internal links with query parameters', () => {
    // Verify initial page is loaded
    cy.get('[data-testid="dashboard-header"]').should('be.visible');

    // Click on an internal link with query parameters
    cy.get('[data-testid="dashboard-reports-link"]').click();

    // Verify the same tab is active
    cy.get('[data-testid="dashboard-header"]').should('be.visible');
    cy.get('[data-testid="dashboard-reports-panel"]').should('be.visible');

    // Verify the URL has changed to include query parameters
    cy.url().should('include', '/dashboard/reports');

    // Verify the content of the new tab matches the expected content
    cy.get('[data-testid="reports-title"]').should('contain', 'Reports');
    cy.get('[data-testid="reports-description"]').should('contain', 'View and generate reports');

    // Verify the back button returns to the original tab
    cy.get('[data-testid="dashboard-reports-back-button"]').click();
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="dashboard-header"]').should('be.visible');
  });
});
